from boltons.excutils import ExceptionCauseMixin

class E(ExceptionCauseMixin):
    pass

def test_it():
    try:
        try:
            raise ValueError('v')
        except ValueError as ve:
            raise E(ve, 'm')
    except E as e:
        assert e.full_trace
        assert 'Wrapped traceback (most recent call last):' in str(e)
